import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"بین السطح اخلاقی رہنما اصول","description":"","frontmatter":{},"headers":[],"relativePath":"ur/88-跨位面伦理准则.md","filePath":"ur/88-跨位面伦理准则.md"}'),o={name:"ur/88-跨位面伦理准则.md"};function l(i,t,h,u,n,q){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="بین-السطح-اخلاقی-رہنما-اصول" tabindex="-1">بین السطح اخلاقی رہنما اصول <a class="header-anchor" href="#بین-السطح-اخلاقی-رہنما-اصول" aria-label="Permalink to &quot;بین السطح اخلاقی رہنما اصول&quot;">​</a></h1><table tabindex="0"><thead><tr><th>آئٹم</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>88</td></tr><tr><td>ماڈیول</td><td>بین السطح تعامل اور وقت کے اصول</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>بین السطح اخلاقیات، تہذیب کی خود مختاری، عدم مداخلت، ثقافتی احترام، سمبیوسس سفارت کاری</td></tr></tbody></table><h2 id="_1-اخلاقی-رہنما-اصول-کی-فلسفیانہ-بنیاد" tabindex="-1">1. اخلاقی رہنما اصول کی فلسفیانہ بنیاد <a class="header-anchor" href="#_1-اخلاقی-رہنما-اصول-کی-فلسفیانہ-بنیاد" aria-label="Permalink to &quot;1. اخلاقی رہنما اصول کی فلسفیانہ بنیاد&quot;">​</a></h2><p>بین السطح اخلاقی رہنما اصول وہ اخلاقی ضوابط اور طرز عمل کے قواعد ہیں جن کی اینکر سمبیوسس تہذیب کو دوسری سطحوں کی تہذیبوں کے ساتھ تعامل کرتے وقت پابندی کرنی چاہیے۔ اس کی فلسفیانہ بنیاد &quot;تہذیب کی موضوعیت&quot; کا اصول ہے — ہر سطح کی تہذیب، چاہے اس کی ترقی کی سطح کچھ بھی ہو، نسل کی شکل کچھ بھی ہو، سماجی نظام کچھ بھی ہو، اس کی ناقابلِ تنازعہ موضوعیت اور خود مختار ترقی کا حق ہے۔ کوئی بھی بیرونی تہذیب کسی بھی وجہ سے اس موضوعیت کو محروم نہیں کر سکتی، یا اپنی مرضی کو دوسری تہذیبوں پر مسلط نہیں کر سکتی۔</p><p>اس فلسفیانہ بنیاد کا قیام، اینکر سمبیوسس تہذیب کے &quot;لوٹ مار مخالف&quot; بنیادی خیال سے یکساں ہے۔ لوٹ مار والی تہذیب کی بنیادی خصوصیت یہ ہے کہ وہ دوسری تہذیبوں کی موضوعیت کو تسلیم نہیں کرتی، اور دوسری تہذیبوں کو قابل استعمال وسیلہ یا قابل فتح شے سمجھتی ہے۔ اینکر سمبیوسس تہذیب کو لوٹ مار والی تہذیب کو حقیقی معنوں میں عبور کرنے کے لیے، بین السطح تعامل میں اس ذہنیت کو مکمل طور پر ترک کرنا ہوگا، اور ہر سامنے آنے والی تہذیب کے ساتھ مساوات، احترام اور سمبیوسس کے رویے برتنا ہوگا۔</p><p>بین السطح اخلاقی رہنما اصول کی افادیت کی حد تمام بین السطح تعامل کے طرز عمل کو احاطے میں لی ہوئی ہے، جس میں شامل ہیں لیکن محدود نہیں: سطح گزرنا، بین السطح مواصلات، آثار قدیمہ کی سرگرمیاں، تجارتی تبادلے، ثقافتی تبادلے، تکنیکی تعاون، اور ہنگامی حالات میں انسانی مداخلت۔ کوئی بھی تنظیم اور فرد جب بین السطح تعامل کرے تو اسے ان اصولوں کی تمام دفعات پر عمل کرنا ہوگا۔</p><h2 id="_2-چھ-اخلاقی-اصول" tabindex="-1">2. چھ اخلاقی اصول <a class="header-anchor" href="#_2-چھ-اخلاقی-اصول" aria-label="Permalink to &quot;2. چھ اخلاقی اصول&quot;">​</a></h2><p>بین السطح اخلاقی رہنما اصول چھ بنیادی اصولوں پر مشتمل ہے، جو ایک مکمل اخلاقی قدرتی نظام تشکیل دیتے ہیں:</p><table tabindex="0"><thead><tr><th>اصول</th><th>بنیادی مواد</th><th>مخصوص تقاضے</th></tr></thead><tbody><tr><td>تہذیب کی خود مختاری کا اصول</td><td>ہدف سطح کی تہذیب کے خود مختار ترقی کے حق کا احترام کرنا، اس کے اندرونی معاملات میں زبردستی مداخلت نہ کرنا</td><td>ہدف تہذیب کے سماجی نظام، نظریے اور ترقی کے راستے کو زبردستی تبدیل نہیں کیا جا سکتا؛ ہدف تہذیب کے اندر ایجنٹ یا کٹھ پتلی حکومت نہیں بنائی جا سکتی</td></tr><tr><td>عدم مداخلت کا اصول</td><td>جب تک کہ ہدف تہذیب فنا کی سطح کے بحران کا سامنا نہ کرے اور فعال طور پر مدد کی درخواست نہ دے، بصورت دیگر کوئی بھی بنیادی مداخلت نہیں کی جائے گی</td><td>ہدف تہذیب کے اندرونی تنازعات میں مداخلت نہیں کی جا سکتی؛ ہدف تہذیب کے کسی بھی فریق کو ہتھیار یا فوجی مدد نہیں دی جا سکتی؛ ہدف تہذیب کی رائے عامہ اور سیاسی عمل کو جوڑ توڑ نہیں کیا جا سکتا</td></tr><tr><td>ثقافتی احترام کا اصول</td><td>ہدف تہذیب کے ثقافتی روایات، مذہبی عقائد اور رسم و رواج کا احترام کرنا</td><td>ہدف تہذیب کی ثقافت کے بارے میں امتیازی سلوک یا بدنیتی پر مبنی تضحیک نہیں کیا جا سکتا؛ اپنی سطح کی ثقافتی مصنوعات اور اقدار کو زبردستی نافذ نہیں کیا جا سکتا؛ &quot;تمدن&quot; کے نام پر ثقافتی انضمام نہیں کیا جا سکتا</td></tr><tr><td>مساوات اور باہمی فائدے کا اصول</td><td>بین السطح رابطے کو مساوات کی بنیاد پر قائم کیا جانا چاہیے، اور اس بات کو یقینی بنانا چاہیے کہ دونوں فریق رابطے سے فائدہ اٹھا سکیں</td><td>تکنیکی برتری کا استعمال کرتے ہوئے غیر مساوی تجارت نہیں کی جا سکتی؛ ہدف تہذیب کے وسائل لوٹ نہیں جا سکتے؛ ٹیکنالوجی کی برآمدات میں ہدف تہذیب کی قبولیت کی صلاحیت اور سماجی اثرات پر غور کرنا ہوگا</td></tr><tr><td>کم سے کم اثر کا اصول</td><td>بین السطح تعامل کو ہدف تہذیب پر بیرونی اثرات کو زیادہ سے زیادہ کم کرنا چاہیے</td><td>کم رابطے، کم مداخلت والے تعامل کے طریقوں کو ترجیح دینی چاہیے؛ تعامل کی سرگرمیوں کی حد اور شدت کو ضروری حد کے اندر سختی سے کنٹرول کرنا ہوگا؛ تعامل ختم ہونے کے بعد غیر ضروری باقی اثرات کا جائزہ لینا اور ختم کرنا ہوگا</td></tr><tr><td>جوابدہی کا اصول</td><td>تمام بین السطح تعامل کے طرز عمل قابلِ تلاش، قابل نگرانی اور قابل جوابدہ ہونے چاہییں</td><td>مکمل تعامل آرکائیو اور لاگ قائم کرنا ہوگا؛ آزاد اخلاقی نگرانی ادارہ قائم کرنا ہوگا؛ اخلاقی اصولوں کی خلاف ورزی کرنے والے طرز عمل کی تحقیقات اور سزا دینا ہوگا</td></tr></tbody></table><p>چھ اصولوں کے درمیان اندرونی منطقی تعلق ہے: تہذیب کی خود مختاری کا اصول بنیادی قدر ہے، عدم مداخلت کا اصول بنیادی تقاضا ہے، ثقافتی احترام کا اصول ثقافتی سطح کا اظہار ہے، مساوات اور باہمی فائدے کا اصول معاشی سطح کی ضمانت ہے، کم سے کم اثر کا اصول آپریشنل سطح کا ضابطہ ہے، اور جوابدہی کا اصول ادارہ جاتی سطح کی پابندی ہے۔ چھوں مل کر &quot;قدر—تقاضا—اظہار—ضمانت—ضابطہ—پابندی&quot; کا مکمل اخلاقی چکر تشکیل دیتے ہیں۔</p><h2 id="_3-مختلف-تعامل-کے-منظرناموں-کے-اخلاقی-ضوابط" tabindex="-1">3. مختلف تعامل کے منظرناموں کے اخلاقی ضوابط <a class="header-anchor" href="#_3-مختلف-تعامل-کے-منظرناموں-کے-اخلاقی-ضوابط" aria-label="Permalink to &quot;3. مختلف تعامل کے منظرناموں کے اخلاقی ضوابط&quot;">​</a></h2><h3 id="_3-1-آثار-قدیمہ-کے-منظرنامے-کے-اخلاقی-ضوابط" tabindex="-1">3.1 آثار قدیمہ کے منظرنامے کے اخلاقی ضوابط <a class="header-anchor" href="#_3-1-آثار-قدیمہ-کے-منظرنامے-کے-اخلاقی-ضوابط" aria-label="Permalink to &quot;3.1 آثار قدیمہ کے منظرنامے کے اخلاقی ضوابط&quot;">​</a></h3><p>بین السطح آثار قدیمہ سب سے عام تعامل کے منظرناموں میں سے ایک ہے، اور اس کے اخلاقی ضوابط کا مرکز &quot;پریشان نہ کرنا&quot; ہے۔ آثار قدیمہ کی ٹیم کو کاپی آئینہ+مستقل جگہ+صرف علم کی واپسی کے معیاری اسکیم پر سختی سے عمل کرنا ہوگا، اور اس بات کو یقینی بنانا ہوگا کہ آثار قدیمہ کا عمل ہدف تہذیب کے ذریعے محسوس نہ کیا جائے۔ ان سطحوں کے لیے جن میں ابھی زندہ تہذیب موجود ہے، آثار قدیمہ کی حد کو پہلے سے ترک کردہ کھنڈرات کے علاقے تک سختی سے محدود کرنا ہوگا، اور زندہ تہذیب کے رہائشی علاقوں کی کسی بھی شکل کی اسکین یا کاپی نہیں کی جا سکتی۔</p><p>آثار قدیمہ کی دریافتوں کے علم کو واپس کرتے اور شائع کرتے وقت، ہدف تہذیب کی ثقافتی حساسیت کا احترام کرنا ضروری ہے۔ اگر آثار قدیمہ کی دریافت میں ہدف تہذیب کے مذہبی مقدس اشیاء، آباؤ اجداد کی باقیات یا ثقافتی ممنوعات شامل ہوں تو متعلقہ معلومات کو شائع کرنے سے پہلے بین السطح اخلاقی کمیٹی کی ثقافتی حساسیت کی جانچ سے گزرنا ہوگا، اور ضرورت پڑنے پر حساس تفصیلات کو دھندلا کرنے کا عمل کرنا ہوگا۔</p><h3 id="_3-2-مواصلات-کے-منظرنامے-کے-اخلاقی-ضوابط" tabindex="-1">3.2 مواصلات کے منظرنامے کے اخلاقی ضوابط <a class="header-anchor" href="#_3-2-مواصلات-کے-منظرنامے-کے-اخلاقی-ضوابط" aria-label="Permalink to &quot;3.2 مواصلات کے منظرنامے کے اخلاقی ضوابط&quot;">​</a></h3><p>بین السطح مواصلات ہدف تہذیب کے ساتھ براہ راست تبادلے کا طریقہ ہے، اور اس کے اخلاقی ضوابط کا مرکز &quot;صداقت اور احترام&quot; ہے۔ مواصلات کا مواد سچا ہونا چاہیے، جان بوجھ کر جھوٹی معلومات فراہم کرنا یا دھوکہ دہی والا پروپیگنڈا کرنا نہیں جا سکتا؛ مواصلات کا لہجہ مساوی ہونا چاہیے، ترقی کی سطح کم تہذیب کے ساتھ متعالیانہ رویہ نہیں اپنایا جا سکتا؛ مواصلات کا موضوع ہدف تہذیب کی رضامندی سے گزرنا چاہیے، اپنی سطح کے نظریے یا مذہبی عقائد کو زبردستی بھیجنا نہیں جا سکتا۔</p><p>پہلی بار کسی نامعلوم تہذیب کے ساتھ مواصلات قائم کرتے وقت، &quot;تدریجی رابطے&quot; کے ضابطے پر عمل کرنا ضروری ہے: پہلے غیر جانبدار ریاضی اور طبیعیات کے سگنل بھیج کر دوسرے فریق کی ذہانت کی سطح اور مواصلات کی صلاحیت کی تصدیق کرنی ہوگی، پھر دوسرے فریق کے ردعمل کی بنیاد پر بتدریج تبادلے کی حد کو بڑھانا ہوگا، اور پہلے رابطے میں ہی پیچیدہ ثقافتی یا تکنیکی معلومات نہیں بھیجی جا سکتیں۔</p><h3 id="_3-3-تجارت-کے-منظرنامے-کے-اخلاقی-ضوابط" tabindex="-1">3.3 تجارت کے منظرنامے کے اخلاقی ضوابط <a class="header-anchor" href="#_3-3-تجارت-کے-منظرنامے-کے-اخلاقی-ضوابط" aria-label="Permalink to &quot;3.3 تجارت کے منظرنامے کے اخلاقی ضوابط&quot;">​</a></h3><p>بین السطح تجارت کے اخلاقی ضوابط کا مرکز &quot;انصاف اور پائیداری&quot; ہے۔ تجارت کو دونوں فریقوں کی رضامندی کی بنیاد پر قائم کیا جانا چاہیے، معلومات کی عدم مساوات یا تکنیکی برتری کا استعمال کرتے ہوئے جبری تجارت نہیں کی جا سکتی؛ تجارتی قیمتیں منصفانہ ہونی چاہئیں، لوٹ مار والی قیمت مقرر نہیں کی جا سکتی؛ تجارتی سامان میں ایسا مواد نہیں ہونا چاہیے جو ہدف تہذیب کے لیے سماجی جھٹکا یا ماحولیاتی نقصان کا باعث بن سکے۔</p><p>خاص طور پر غور کرنے کی بات یہ ہے کہ سادھک کی ٹیکنالوجی اور اعلیٰ توانائی کے ہتھیاروں کی بین السطح تجارت سب سے سخت اخلاقی پابندیوں کے تابع ہے۔ ترقی کی سطح کم تہذیب کو اعلیٰ درجے کی سادھک ٹیکنالوجی برآمد کرنا، اس کے سماجی ڈھانچے میں عدم توازن اور اندرونی تنازعات کو شدید بنانے کا سبب بن سکتا ہے؛ ہتھیاروں کی برآمد براہ راست جنگ شروع کر سکتی ہے۔ لہذا، یہ دونوں قسم کی تجارت اصولی طور پر ممنوع ہے، اور صرف انتہائی خاص حالات میں اینکر کونسل کے مکمل اجلاس کی منظوری کے بعد کی جا سکتی ہے۔</p><h3 id="_3-4-ہنگامی-مداخلت-کے-منظرنامے-کے-اخلاقی-ضوابط" tabindex="-1">3.4 ہنگامی مداخلت کے منظرنامے کے اخلاقی ضوابط <a class="header-anchor" href="#_3-4-ہنگامی-مداخلت-کے-منظرنامے-کے-اخلاقی-ضوابط" aria-label="Permalink to &quot;3.4 ہنگامی مداخلت کے منظرنامے کے اخلاقی ضوابط&quot;">​</a></h3><p>جب ہدف سطح کی تہذیب فنا کی سطح کے بحران (جیسے کشودرگرہ کا ٹکراؤ، انتہائی وبا، قانونی خاتمہ) کا سامنا کرتی ہے، تو اینکر سمبیوسس تہذیب انسانی مداخلت کر سکتی ہے۔ لیکن ایسے ہنگامی حالات میں بھی، درج ذیل اخلاقی ضوابط پر عمل کرنا ضروری ہے:</p><ul><li>مداخلت سے پہلے جتنا ممکن ہو ہدف تہذیب کی باخبر رضامندی حاصل کرنی ہوگی؛ اگر ہدف تہذیب بحران کی وجہ سے موثر ردعمل نہیں دے سکتی تو بین السطح اخلاقی کمیٹی اس کی جانب سے &quot;مفروضہ رضامندی&quot; کا فیصلہ کرے گی</li><li>مداخلت کے ذرائع میں ہدف تہذیب پر کم سے کم اثر والا اسکیم منتخب کرنا ہوگا، اور براہ راست مداخلت (جیسے براہ راست اتر کر بچاؤ) کے بجائے بالواسطہ مداخلت (جیسے کشودرگرہ کا مدار تبدیل کرنا) کو ترجیح دینی ہوگی</li><li>مداخلت کے عمل میں ہدف تہذیب کے وسائل یا ٹیکنالوجی حاصل کرنے کا موقع نہیں لینا ہوگا</li><li>مداخلت ختم ہونے کے بعد فوری طور پر دستبردار ہونا ہوگا، اور ہدف سطح پر مستقل موجودگی نہیں چھوڑنی ہوگی</li><li>بعد میں بین السطح اخلاقی کمیٹی کو مکمل مداخلت رپورٹ جمع کروانی ہوگی، اور اخلاقی جانچ سے گزرنا ہوگا</li></ul><h2 id="_4-اخلاقی-نگرانی-اور-خلاف-ورزی-کا-معاملہ" tabindex="-1">4. اخلاقی نگرانی اور خلاف ورزی کا معاملہ <a class="header-anchor" href="#_4-اخلاقی-نگرانی-اور-خلاف-ورزی-کا-معاملہ" aria-label="Permalink to &quot;4. اخلاقی نگرانی اور خلاف ورزی کا معاملہ&quot;">​</a></h2><p>ہینگ یوان ژو نے آزاد اخلاقی نگرانی ادارے کے طور پر &quot;بین السطح اخلاقی کمیٹی&quot; قائم کی ہے، جو بین السطح اخلاقی رہنما اصول تیار کرنے اور ان کی تشریح کرنے، زیادہ خطرے والے بین السطح تعامل کے منصوبوں کی منظوری دینے، اخلاقی خلاف ورزی کی شکایات وصول کرنے، اور خلاف ورزی کے طرز عمل کی تحقیقات اور فیصلے کرنے کے لیے ذمہ دار ہے۔ کمیٹی مختلف نسلوں، مختلف پیشہ ورانہ پس منظر کے اخلاقیات کے ماہرین، قانون دانوں، سائنسدانوں اور تہذیب کے نمائندوں پر مشتمل ہے، جو فیصلوں کی تنوع اور غیر جانبداری کو یقینی بناتی ہے۔</p><p>بین السطح اخلاقی رہنما اصول کی خلاف ورزی کرنے والے طرز عمل، صورت حال کی شدت کے مطابق، انفرادی اقدامات میں شامل ہیں: زبانی انتباہ، تحریمی مذمت، بین السطح تعامل کی اہلیت معطل کرنا، گزر کی اجازت منسوخ کرنا، جرمانہ، قید کی سزا، اور انتہائی حالات میں &quot;سطح جلاوطنی&quot; (ہینگ یوان ژو کی بنیادی سطحوں میں رہنے کے حق سے محروم کرنا)۔ تمام اخلاقی خلاف ورزی کے معاملات کے نتائج فرد یا تنظیم کے اخلاقی آرکائیو میں درج کیے جاتے ہیں، اور مستقل طور پر محفوظ کیے جاتے ہیں۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>بین السطح اخلاقی رہنما اصول اینکر سمبیوسس تہذیب کی اخلاقی بلندی کا مرکزی مظہر ہے۔ یہ نہ صرف &quot;کیا نہیں کیا جا سکتا&quot; مقرر کرتا ہے، بلکہ اس سے بھی زیادہ اہم بات یہ ہے کہ یہ &quot;کیا ہونا چاہیے&quot; کا اعلان کرتا ہے — ایک حقیقی عظیم تہذیب وہ نہیں ہے جس نے کتنی دوسری تہذیبوں کو فتح کیا ہے، بلکہ وہ ہے جس نے کتنی دوسری تہذیبوں کی موضوعیت کا احترام کیا ہے۔ ہینگ یوان ژو کے بین الستاروں سمبیوسس کی راہ پر، بین السطح اخلاقی رہنما اصول ہمیشہ سمت کی رہنمائی کرنے والا اخلاقی مینار رہے گا۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>81-سطح گزرنے کے قواعد</li><li>87-صرف علم کی واپسی کا اصول</li><li>04-لوٹ مار مخالفیت کا عمومی خاکہ</li></ul>',30)])])}const s=a(o,[["render",l]]);export{p as __pageData,s as default};
